SELECT c.id AS id, c.contract_no AS contractNo, c.contract_name AS contractName, c.business_entity_id AS businessEntityId, be.name AS businessEntityName, c.contract_direction AS contractDirection, c.contract_type AS contractType, c.related_party_id AS relatedPartyId, c.related_party_type AS relatedPartyType, c.signing_entity AS signingEntity, c.valid_from AS validFrom, c.valid_to AS validTo, c.amount AS amount, c.file_url AS fileUrl, c.double_seal_file_url AS doubleSealFileUrl, c.seal_status AS sealStatus, c.status AS status, c.organization_id AS organizationId, c.create_time AS createTime FROM ad_contract c LEFT JOIN ad_business_entity be ON be.id = c.business_entity_id AND be.deleted = 0 WHERE c.organization_id = #{request.organizationId} AND c.deleted = 0
AND c.contract_direction = #{request.contractDirection}
AND c.contract_type = #{request.contractType}
AND c.related_party_type = #{request.relatedPartyType}
AND c.status = #{request.status}
AND c.seal_status = #{request.sealStatus}
AND c.business_entity_id = #{request.businessEntityId}
AND c.change_order_id = #{request.changeOrderId}
AND (c.contract_no LIKE CONCAT('%', #{request.keyword}, '%') OR c.contract_name LIKE CONCAT('%', #{request.keyword}, '%'))
AND c.valid_from >= #{request.validFromFrom}
AND c.valid_to <= #{request.validFromTo}
AND c.business_entity_id IN
#{eid}

SELECT COUNT(1)
FROM ad_contract
WHERE organization_id = #{orgId}
  AND deleted = 0
  AND create_time >= #{start}
  AND create_time <= #{end}
